import style from "../../CSS/userSide/shippingAddressForm.module.css";
import { type } from './../../../.next/types/routes.d';
export default function ShippingAddress() {
  return (
    <div className={style.FormContainer}>
      <div className={style.title}>
        <h3>Shipping Address</h3>
      </div>
      <div>
        <form className={style.FormSection}>
          <div className={style.inputSection}>
            <label htmlFor=""></label>
            <div className={style.inputGroup}>
              <select defaultValue={""}>
                <option value={""}>Select a province</option>
              </select>
            </div>
          </div>
          <div className={style.inputSection}>
            <label></label>
            <div className={style.inputGroup}>
              <select defaultValue={""}>
                <option value={""}>Select a district</option>
              </select>
            </div>
          </div>
          <div className={style.inputSection}>
            <label htmlFor=""></label>
            <div className={style.inputGroup}>
              <select defaultValue={""}>
                <option value={""}>Select a municipality</option>
              </select>
            </div>
          </div>
          <div className={style.inputSection}>
            <label htmlFor=""></label>
            <div className={style.inputGroup}>
              <select defaultValue={""}>
                <option value={""}>Select a wardNumber</option>
              </select>
            </div>
          </div>
          <div className={style.inputSection}>
            <label htmlFor="">Land Mark</label>
            <div className={style.inputGroup}>
              <input 
              type="number"
              placeholder="Enter a ward number"
              />
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}
